// ============================================================
// ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ============================================================

function getAuthorById(id) {
    return authorsData.find(author => author.id === id);
}

function escapeHtml(str) {
    if (!str) return "";
    return str
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

function getWorksDeclension(count) {
    if (count % 10 === 1 && count % 100 !== 11) return "работа";
    if (count % 10 >= 2 && count % 10 <= 4 && (count % 100 < 10 || count % 100 >= 20)) return "работы";
    return "работ";
}

// ============================================================
// УВЕДОМЛЕНИЯ (TOAST)
// ============================================================

function showToast(message, type = "warning") {
    // Удаляем старый тост, если есть
    const oldToast = document.querySelector(".toast-notification");
    if (oldToast) {
        oldToast.remove();
    }
    
    const toast = document.createElement("div");
    toast.className = `toast-notification toast-${type}`;
    toast.innerHTML = `
        <span class="toast-icon">${type === "warning" ? "⚠️" : "ℹ️"}</span>
        <span class="toast-message">${escapeHtml(message)}</span>
    `;
    
    document.body.appendChild(toast);
    
    // Анимация появления
    setTimeout(() => {
        toast.classList.add("toast-show");
    }, 10);
    
    // Автоматическое исчезновение через 3 секунды
    setTimeout(() => {
        toast.classList.remove("toast-show");
        setTimeout(() => {
            if (toast.parentNode) {
                toast.remove();
            }
        }, 300);
    }, 3000);
}

// ============================================================
// МОДАЛЬНОЕ ОКНО
// ============================================================

const modal = {
    element: null,
    titleEl: null,
    biblioEl: null,
    openBtn: null,
    closeBtn: null,
    currentUrl: null,
    currentTitle: null,
    
    init() {
        this.element = document.getElementById("workModal");
        this.titleEl = document.getElementById("modalTitle");
        this.biblioEl = document.getElementById("modalBiblio");
        this.openBtn = document.getElementById("modalOpenBtn");
        this.closeBtn = document.getElementById("modalClose");
        
        if (this.closeBtn) {
            this.closeBtn.addEventListener("click", () => this.close());
        }
        
        if (this.element) {
            const overlay = this.element.querySelector(".modal-overlay");
            if (overlay) {
                overlay.addEventListener("click", () => this.close());
            }
        }
        
        if (this.openBtn) {
            this.openBtn.addEventListener("click", () => {
                if (this.currentUrl && this.currentUrl !== "") {
                    window.open(this.currentUrl, "_blank");
                } else {
                    showToast("Ссылка на работу отсутствует", "warning");
                }
            });
        }
        
        document.addEventListener("keydown", (e) => {
            if (e.key === "Escape" && this.isOpen()) {
                this.close();
            }
        });
    },
    
    open(title, biblio, url) {
        if (!this.element) return;
        
        this.currentUrl = url || "";
        this.currentTitle = title;
        
        if (this.titleEl) {
            this.titleEl.textContent = title;
        }
        
        if (this.biblioEl) {
            if (biblio && biblio.trim() !== "") {
                this.biblioEl.innerHTML = `<div class="modal-biblio">${escapeHtml(biblio)}</div>`;
            } else {
                this.biblioEl.innerHTML = `<div class="modal-biblio modal-biblio-missing">📋 Библиографическое описание отсутствует</div>`;
            }
        }
        
        this.element.classList.add("active");
        document.body.style.overflow = "hidden";
    },
    
    close() {
        if (!this.element) return;
        
        this.element.classList.remove("active");
        document.body.style.overflow = "";
        this.currentUrl = null;
    },
    
    isOpen() {
        return this.element && this.element.classList.contains("active");
    }
};

// ============================================================
// ГЛАВНАЯ СТРАНИЦА (index.html)
// ============================================================

if (window.location.pathname.includes("index.html") || 
    window.location.pathname === "/" || 
    window.location.pathname.endsWith("/")) {
    
    document.addEventListener("DOMContentLoaded", () => {
        const grid = document.getElementById("authorsGrid");
        const totalSpan = document.getElementById("totalCount");
        const totalWorksSpan = document.getElementById("totalWorks");
        const searchInput = document.getElementById("searchInput");
        const sortSelect = document.getElementById("sortSelect");
        const resultsInfo = document.getElementById("resultsInfo");

        if (grid) {
            // Общая статистика
            totalSpan.textContent = authorsData.length;
            const totalWorks = authorsData.reduce((sum, a) => sum + a.works.length, 0);
            if (totalWorksSpan) totalWorksSpan.textContent = totalWorks;

            function getSortedAuthors(authors, sortVal) {
                const arr = [...authors];
                if (sortVal === "name-asc") arr.sort((a, b) => a.name.localeCompare(b.name, "ru"));
                else if (sortVal === "name-desc") arr.sort((a, b) => b.name.localeCompare(a.name, "ru"));
                else if (sortVal === "works-desc") arr.sort((a, b) => b.works.length - a.works.length);
                else if (sortVal === "works-asc") arr.sort((a, b) => a.works.length - b.works.length);
                return arr;
            }

            function renderAuthors(filterText = "", sortVal = "name-asc") {
                grid.innerHTML = "";
                let filtered = authorsData.filter(author =>
                    author.name.toLowerCase().includes(filterText.toLowerCase())
                );
                const sorted = getSortedAuthors(filtered, sortVal);

                // Счётчик результатов
                if (resultsInfo) {
                    if (filterText) {
                        resultsInfo.textContent = `Найдено: ${sorted.length} из ${authorsData.length} авторов`;
                    } else {
                        resultsInfo.textContent = "";
                    }
                }

                sorted.forEach((author, index) => {
                    const card = document.createElement("div");
                    card.className = "author-card";
                    card.style.setProperty('--index', index);

                    const worksCount = author.works.length;
                    const worksBadge = worksCount > 0
                        ? `<span class="author-works-count">${worksCount} ${getWorksDeclension(worksCount)}</span>`
                        : `<span class="author-works-count">нет работ</span>`;

                    card.innerHTML = `
                        <div class="author-name">
                            <span class="author-name-text">${escapeHtml(author.name)}</span>
                            ${worksBadge}
                        </div>
                    `;

                    card.addEventListener("click", () => {
                        window.location.href = `author.html?id=${author.id}`;
                    });

                    grid.appendChild(card);
                });

                if (sorted.length === 0) {
                    grid.innerHTML = `<div class="empty-works" style="grid-column:1/-1; margin-top:1rem;">Ничего не найдено по запросу «${escapeHtml(filterText)}»</div>`;
                }
            }

            function update() {
                renderAuthors(
                    searchInput ? searchInput.value : "",
                    sortSelect ? sortSelect.value : "name-asc"
                );
            }

            if (searchInput) searchInput.addEventListener("input", update);
            if (sortSelect) sortSelect.addEventListener("change", update);

            renderAuthors("", "name-asc");
        }
    });
}

// ============================================================
// СТРАНИЦА АВТОРА (author.html)
// ============================================================

if (window.location.pathname.includes("author.html")) {
    document.addEventListener("DOMContentLoaded", () => {
        modal.init();

        const urlParams = new URLSearchParams(window.location.search);
        const authorId = parseInt(urlParams.get("id"));
        const author = getAuthorById(authorId);

        const authorNameEl = document.getElementById("authorName");
        const worksListEl = document.getElementById("worksList");
        const worksCountEl = document.getElementById("worksCount");
        const worksFilterEl = document.getElementById("worksFilter");
        const worksSearchInput = document.getElementById("worksSearchInput");

        if (!author) {
            authorNameEl.textContent = "Автор не найден";
            worksListEl.innerHTML = `<div class="empty-works">Автор не найден в библиотеке</div>`;
            return;
        }

        document.title = `${author.name} | Архив публикаций кафедры онтологии и теории познания`;
        authorNameEl.textContent = author.name;

        if (worksCountEl) worksCountEl.textContent = author.works.length;

        if (!author.works || author.works.length === 0) {
            worksListEl.innerHTML = `<div class="empty-works">У этого автора пока нет опубликованных работ</div>`;
            return;
        }

        function buildFilters() {
            if (!worksFilterEl) return;
            // Фильтр по ссылке убран — показываем только «Все»
            worksFilterEl.style.display = "none";
        }

        function renderWorks() {
            worksListEl.innerHTML = "";
            const searchVal = worksSearchInput ? worksSearchInput.value.toLowerCase() : "";

            let filtered = author.works.filter(w => {
                return !searchVal || w.title.toLowerCase().includes(searchVal);
            });

            if (worksCountEl) worksCountEl.textContent = filtered.length;

            if (filtered.length === 0) {
                worksListEl.innerHTML = `<div class="empty-works">Ничего не найдено</div>`;
                return;
            }

            filtered.forEach((work, idx) => {
                const hasUrl = work.url && work.url.trim() !== "";
                const workDiv = document.createElement("div");
                workDiv.className = "work-item";
                workDiv.style.animationDelay = `${idx * 0.02}s`;
                workDiv.innerHTML = `
                    <div class="work-item-left">
                        <span class="work-link-dot ${hasUrl ? "" : "no-link"}" title="${hasUrl ? "Ссылка доступна" : "Ссылка отсутствует"}"></span>
                        <div class="work-title">${escapeHtml(work.title)}</div>
                    </div>
                    <div class="work-arrow">→</div>
                `;
                workDiv.addEventListener("click", () => {
                    modal.open(work.title, work.biblio || "", work.url || "");
                });
                worksListEl.appendChild(workDiv);
            });
        }

        buildFilters();
        renderWorks();

        if (worksSearchInput) {
            worksSearchInput.addEventListener("input", renderWorks);
        }
    });
}